function render(){refreshDerived();$('relationshipControls').hidden=state.tab!=='relationship-details';$('relationshipAdultEnabled').checked=state.settings.adultEnabled;$('relationshipAdultEnabled').disabled=!F.adult(state);K.validateCandidate(state,fields,candidateAllowed);renderDialogueTools();$('canvasView').hidden=state.tab!=='build';$('backToCharacter').hidden=state.tab==='build';$('viewMenu').value=['build','quick'].includes(state.tab)?'':state.tab;document.body.classList.toggle('building',state.tab==='build');document.body.classList.toggle('brief-view',state.tab==='brief');if(state.tab==='build')renderCanvas();else{$('candidateContent').innerHTML='';$('candidatePanel').hidden=true;}if(foundationEditorId&&$('fieldEditorDialog').open)$('fieldEditorContent').innerHTML=card(findField(foundationEditorId));$('momentControls').hidden=!['quick','full','now'].includes(state.tab);$('momentSummary').hidden=$('momentControls').hidden;$('momentWarnings').hidden=$('momentControls').hidden;$('momentSummary').textContent='All readings, messages, sightings, and statuses are fictional. '+(state.settings.footprint==='Random archetype'?'This roll: '+state.settings.resolvedFootprint+'. ':'')+R.warnings(state).join(' · ');$('momentWarnings').textContent=R.warnings(state).length?'Conflicting combinations are preserved for you to curate.':'';const age=getAge();$('settingsSummary').textContent=`${state.settings.storyDate||state.settings.storyYear} · ${state.settings.ageRange} · ${age===null?'Birthday pending':state.settings.storyDate?'Age '+age:'Turns '+age}`;$('characterName').value=state.name;$('keptCount').textContent=keptEntries().length;$('savedCount').textContent=saved.length;for(const b of document.querySelectorAll('[data-tab]')){b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-pressed',b.dataset.tab===state.tab);}$('results').hidden=!['quick','full','dialogue','now','medical','education','relationship-details','criminal-history'].includes(state.tab);$('pickerTools').hidden=$('results').hidden;$('groupWrap').hidden=!['full','dialogue','now','medical','education','relationship-details','criminal-history'].includes(state.tab);$('quickCustomize').hidden=state.tab!=='quick';$('sheetView').hidden=state.tab!=='sheet';$('savedView').hidden=state.tab!=='saved';if(! $('results').hidden)renderResults();if(state.tab==='sheet')renderSheet();if(state.tab==='saved')renderSaved();$('workshopView').hidden=!['history','connections','pressure','brief'].includes(state.tab);if(!$('workshopView').hidden)renderWorkshop();updateHistoryControls();window.GuidedUI?.render();}
function syncInputs(){for(const key of ['storyYear','storyDate','ageRange','traitCount','focusDensity','footprint','perspective','momentMode'])$(key).value=state.settings[key];$('adultEnabled').checked=state.settings.adultEnabled;$('dialogueWildcards').checked=state.settings.dialogueWildcards;$('dialogueCombine').checked=state.settings.dialogueCombine;}
function updateSetting(key,el=$(key)){const old={...state.settings};if(['adultEnabled','dialogueWildcards','dialogueCombine'].includes(key))state.settings[key]=el.checked;else if(['storyYear','traitCount','focusDensity'].includes(key))state.settings[key]=Number(el.value);else state.settings[key]=el.value;const s=state.settings;if(!Number.isInteger(s.storyYear)||s.storyYear<1||s.storyYear>9999||(s.storyDate&&!C.parseDate(s.storyDate))){state.settings=old;syncInputs();toast('Use a valid year from 1 to 9999 or a valid story date.');return;}if(key==='storyDate'&&s.storyDate)s.storyYear=C.parseDate(s.storyDate).y;if(key==='storyYear'&&s.storyDate&&C.parseDate(s.storyDate).y!==s.storyYear)s.storyDate='';if(key==='traitCount'){rebuild();for(const f of fields.filter(f=>f.id.startsWith('trait.')))if(!fieldState(f.id).value)rollField(f);if(state.quickFields){for(const f of fields.filter(f=>f.id.startsWith('trait.')))if(!state.quickFields.includes(f.id))state.quickFields.push(f.id);}}if(key==='adultEnabled'&&adultAllowed()&&!fieldState('SEX_KINK').value)rollField(fields.find(f=>f.id==='SEX_KINK'));if(key==='footprint'){R.begin(state);toast('Footprint applies to future rolls. Existing results are preserved.');}if(key==='momentMode'&&s.momentMode==='Connected moment')for(const id of ['now.setting','now.spot','now.goal','now.conversation.partner'])R.reconcile(state,fields,O,id);if(['storyDate','storyYear'].includes(key))reconcileLife(state,'birthday',O);syncInputs();render();store('Change '+key);}
