function toggleCardFocus(article){const v=fieldState(article.dataset.field);v.focused=!v.focused;article.classList.toggle('focused',v.focused);article.classList.toggle('faded',!v.focused);const button=article.querySelector('[data-action="focus"]');button.setAttribute('aria-pressed',String(v.focused));button.textContent=v.focused?'In focus':'Focus';store('Toggle focus: '+findField(article.dataset.field).label);}
function fieldClick(e){const b=e.target.closest('[data-action]');if(!b){const article=e.target.closest('[data-field]');if(!article||e.target.closest('button,a,input,select,textarea,label,details,summary,[contenteditable]'))return;if(window.getSelection()?.isCollapsed===false)return;toggleCardFocus(article);return;}if(b.dataset.action==='focus'){toggleCardFocus(b.closest('[data-field]'));return;}const article=b.closest('[data-field]'),f=fields.find(f=>f.id===article.dataset.field),v=fieldState(f.id);if(b.disabled||!F.available(f,state))return;const action=b.dataset.action;if(action==='lock')v.locked=!v.locked;if(action==='keep'){v.kept=!v.kept;v.keptValue=v.kept?display(f):'';if(article.dataset.mode==='candidate'){state.canvas.candidateId=null;state.canvas.suggesting=false;}}if(action==='reroll'&&!rerollOne(f))return;if(action==='applyEdit'){if(f.kind==='criminal'||f.kind==='life'){try{(f.kind==='criminal'?H:F).edit(f,state,article.querySelector('.custom-value').value);}catch(error){toast(error.message);return;}}else if(f.numeric){try{M.edit(f,state,article.querySelector('.medical-number').value,article.querySelector('.medical-unit')?.value);}catch(err){toast(err.message);return;}}else if(f.kind==='birthday'){const val=article.querySelector('.birthday-editor').value;if(!C.parseDate(val)){toast('Enter a valid birth date.');return;}if(C.ageAt(val,state.settings.storyYear,state.settings.storyDate)<0){toast('That birthday is after the story date.');return;}v.value=val;}else{const text=article.querySelector('.custom-value').value;if(f.kind==='dialogue'){if(article._dialogueDraft&&text===article._dialogueDraft.value)Object.assign(v,article._dialogueDraft);else if(text!==v.value){v.value=text;v.optionId='';v.parameters={};}}else v.value=text;if(f.kind==='rightNow'){v.information='Available';R.reconcile(state,fields,O,f.id);}}if(!f.numeric)M.reconcile(state,f.id);reconcileLife(state,f.id,O);reconcileLanguages(f.id);refreshDerived();if(v.kept){v.keptValue=display(f);B.sync(state,f.id,v.value);}toast('Updated.');}render();store((action==='keep'?(v.kept?'Keep ':'Remove '):action==='lock'?'Toggle lock: ':action==='applyEdit'?'Edit ':action==='reroll'?'Reroll ':'Change ')+f.label);}
function fieldChange(e){
 const article=e.target.closest('[data-field]');if(!article)return;
 const f=fields.find(f=>f.id===article.dataset.field);
 if(f.kind==='dialogue'&&(e.target.matches('.pool-select')||e.target.matches('[data-dialogue-param]'))){
  const v=fieldState(f.id),entry=e.target.matches('.pool-select')?f.pool[Number(e.target.value)]:f.pool.find(o=>o.id===(article._dialogueDraft?.optionId||v.optionId));if(!entry||e.target.matches('.pool-select')&&e.target.value==='')return;
  try{const parameters=readDialogueParameters(article);if(e.target.dataset.dialogueParam==='languages')parameters.languageOverride=true;article._dialogueDraft=G.prepare(f,state,entry,parameters);article.querySelector('.dialogue-param-fields').innerHTML=dialogueParameters(f,article._dialogueDraft);article.querySelector('.custom-value').value=article._dialogueDraft.value;}catch(err){toast(err.message);}return;
 }
 if(!e.target.matches('.pool-select')||e.target.value==='')return;
 const entry=f.pool[Number(e.target.value)];article.querySelector('.custom-value').value=typeof entry==='object'?entry.name+'\nUpright: '+entry.upright+'\nReversed: '+entry.reversed+'\nKeyword: '+entry.keyword:entry;
}
