async function copyText(txt,success){try{await navigator.clipboard.writeText(txt);toast(success);}catch{const a=document.createElement('textarea');a.value=txt;a.style.position='fixed';a.style.top='0';document.body.append(a);a.select();let ok=false;try{ok=document.execCommand('copy');}catch{}a.remove();toast(ok?success:'Copy is unavailable here. Select the recipe text or export the character.');}}
