function workshopState(){return state.workshop||(state.workshop=T.defaults());}
function makeConnection(role,name='',sourceId=''){
 const w=workshopState();if(w.connections.length>=12){toast('Keep up to 12 connected characters in a draft.');return null;}if(!T.roles.includes(role))role='Friend';
 const owner=state,ownerFields=fields,entries=keptEntries(),source=saved.find(x=>x.id===sourceId);let character;
 try{
  if(source)character=validSnapshot(source.character);
  else{
   state={version:1,name:name.trim().slice(0,150)||'Unnamed '+role.toLowerCase(),notes:'',tab:'build',values:{},settings:JSON.parse(JSON.stringify(owner.settings)),quickFields:owner.quickFields?[...owner.quickFields]:null,canvas:K.defaults(),workshop:T.defaults()};rebuild();rollValues();
   const sharedIds=role==='Sibling'?['CHARACTER_NATIONAL_HERITAGE','birthplace']:role==='Coworker'?['background.occupation']:[];
   for(const id of sharedIds){const v=entries.find(e=>e.id===id)?.value||owner.values[id]?.value;if(v)fieldState(id).value=v;}
   L.reconcile(state,L.heritage);G.refreshLanguages(state);refreshDerived();
   const ownerTrait=entries.find(e=>e.id.startsWith('trait.'))?.value||owner.values['trait.0']?.value;const trait=fields.find(f=>f.id==='trait.0');if(trait&&fieldState(trait.id).value===ownerTrait)fieldState(trait.id).value=C.pick(trait.pool.filter(x=>x!==ownerTrait));
   for(const id of ['trait.0','background.occupation','personality.motivations'])if(state.values[id]){state.values[id].kept=true;state.values[id].keptValue=state.values[id].value;}
   character=JSON.parse(JSON.stringify(state));
  }
 }catch(e){toast(e.message||'Could not generate this connection.');return null;}finally{state=owner;fields=ownerFields;}
 character.workshop=T.defaults();if(name.trim())character.name=name.trim().slice(0,150);
 const item=T.connection(role,character,entries,makeId());w.connections.unshift(item);render();store('Add connected '+role.toLowerCase());return item;
}
